INSERT INTO `exercicioclasse` (`ID`, `IdExercicio`, `IdAluno`, `NomeClasse`, `Codigo`, `CodigoAnterior`, `DataCadastro`, `Favorito`) VALUES
(13, 20, 10, 'Ponto', '/**\r\n *\r\n * @author gilvani\r\n */\r\npublic class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n', '/**\r\n *\r\n * @author gilvani\r\n */\r\npublic class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    private int t;\r\n    \r\n    public Ponto()\r\n    {\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n', '2015-05-14 04:32:35', 0),
(14, 20, 10, 'Reta', '/*\r\n * To change this license header, choose License Headers in Project Properties.\r\n * To change this template file, choose Tools | Templates\r\n * and open the template in the editor.\r\n */\r\n\r\n/**\r\n *\r\n * @author gilvani\r\n */\r\npublic class Reta {\r\n\r\n    private Ponto p;\r\n    private Ponto q;\r\n\r\n    public Reta() {\r\n    }\r\n\r\n    public Reta(Ponto p, Ponto q) {\r\n        this.p = p;\r\n        this.q = q;\r\n    }\r\n\r\n    public Ponto getP() {\r\n        return p;\r\n    }\r\n\r\n    public void setP(Ponto p) {\r\n        this.p = p;\r\n    }\r\n\r\n    public Ponto getQ() {\r\n        return q;\r\n    }\r\n\r\n    public void setQ(Ponto q) {\r\n        this.q = q;\r\n    }\r\n\r\n    public double getDistancia() {\r\n        double x = Math.pow(q.getX() - p.getX(), 2);\r\n        double y = Math.pow(q.getY() - p.getY(), 2);\r\n        return Math.sqrt(x + y);\r\n    }\r\n}\r\n', '/*\r\n * To change this license header, choose License Headers in Project Properties.\r\n * To change this template file, choose Tools | Templates\r\n * and open the template in the editor.\r\n */\r\n\r\n/**\r\n *\r\n * @author gilvani\r\n */\r\npublic class Reta {\r\n\r\n    private Ponto p;\r\n    private Ponto q;\r\n\r\n    public Reta() {\r\n    }\r\n\r\n    public Reta(Ponto p, Ponto q) {\r\n        this.p = p;\r\n        this.q = q;\r\n    }\r\n\r\n    public Ponto getP() {\r\n        return p;\r\n    }\r\n\r\n    public void setP(Ponto p) {\r\n        this.p = p;\r\n    }\r\n\r\n    public Ponto getQ() {\r\n        return q;\r\n    }\r\n\r\n    public void setQ(Ponto q) {\r\n        this.q = q;\r\n    }\r\n\r\n    public double getDistancia() {\r\n        double x = Math.pow(q.getX() - p.getX(), 2);\r\n        double y = Math.pow(q.getY() - p.getY(), 2);\r\n        return Math.sqrt(x + y);\r\n    }\r\n}\r\n', '2015-05-22 02:54:23', 0),
(15, 20, 20, 'Ponto', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Ponto {\r\n   private int x, y;\r\n   \r\n   public Ponto ( ) {\r\n       x = y = 0;\r\n   }\r\n   \r\n   public Ponto (int x, int y) {\r\n       this.x = x;\r\n       this.y = y;\r\n   }\r\n   \r\n   public int getX ( ) {\r\n       return x;\r\n   }\r\n   \r\n   public int getY ( ) {\r\n       return y;\r\n   }\r\n   \r\n   public void setX (int x) {\r\n       this.x = x;\r\n   }\r\n   \r\n   public void setY (int y) {\r\n       this.y = y;\r\n   }\r\n   \r\n   public String toString ( ) {\r\n       return "(" + x + ", " + y + ")";\r\n   }\r\n}', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Ponto {\r\n   private int x, y;\r\n   \r\n   public Ponto ( ) {\r\n       x = y = 0;\r\n   }\r\n   \r\n   public Ponto (int x, int y) {\r\n       this.x = x;\r\n       this.y = y;\r\n   }\r\n   \r\n   public getX ( ) {\r\n       return x;\r\n   }\r\n   \r\n   public getY ( ) {\r\n       return y;\r\n   }\r\n   \r\n   public setX (int x) {\r\n       this.x = x;\r\n   }\r\n   \r\n   public setY (int y) {\r\n       this.y = y;\r\n   }\r\n   \r\n   public String toString ( ) {\r\n       return "(" + x + ", " + y + ")";\r\n   }\r\n}', '2015-05-08 17:54:14', 0),
(16, 20, 20, 'Reta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Reta {\r\n   private Ponto p, q;\r\n   \r\n   public Reta ( ) {\r\n       p = q = null;\r\n   }\r\n   \r\n   public Reta (Ponto p, Ponto q) {\r\n       this.p = p;\r\n       this.q = q;\r\n   }\r\n   \r\n   public Ponto getP ( ) {\r\n       return p;\r\n   }\r\n   \r\n   public Ponto getQ ( ) {\r\n       return q;\r\n   }\r\n   \r\n   public void setP (Ponto p) {\r\n       this.p = p;\r\n   }\r\n   \r\n   public void setQ (Ponto q) {\r\n       this.q = q;\r\n   }\r\n   \r\n   public double getDistancia ( ) {\r\n       return Math.sqrt (Math.pow ((q.getX ( ) - p.getX ( )), 2) + Math.pow ((q.getY ( ) - p.getY ( )), 2));\r\n   }\r\n}', NULL, '2015-05-08 17:53:27', 0),
(18, 20, 11, 'Ponto', '\r\n/**\r\n * @author (Delon) \r\n * @version (08/05/2015)\r\n */\r\npublic class Ponto{\r\n    private int x;\r\n    private int y;\r\n    \r\n    //Construtor - Sem argumentos\r\n    public Ponto(){\r\n    }\r\n    \r\n    //Construtor - Com argumentos\r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    //Método SET de x\r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n\r\n    //Método SET de y\r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    //Método GET de x\r\n    public int getX(){\r\n        return this.x;\r\n    }\r\n    \r\n    //Método GET de x\r\n    public int getY(){\r\n        return this.y;\r\n    }\r\n    \r\n    //Método toString\r\n    public String toString(){\r\n        return "(" + this.x + ", " + this.y + ")";\r\n    }\r\n}', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\n/**\r\n * @author (Delon) \r\n * @version (08/05/2015)\r\n */\r\npublic class Ponto{\r\n    private int x;\r\n    private int y;\r\n    \r\n    //Construtor - Sem argumentos\r\n    public Ponto(){\r\n    }\r\n    \r\n    //Construtor - Com argumentos\r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    //Método SET de x\r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n\r\n    //Método SET de y\r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    //Método GET de x\r\n    public int getX(){\r\n        return this.x;\r\n    }\r\n    \r\n    //Método GET de x\r\n    public int getY(){\r\n        return this.y;\r\n    }\r\n    \r\n    //Método toString\r\n    public String toString(){\r\n        return "(" + this.x + ", " + this.y + ")";\r\n    }\r\n}', '2015-05-14 21:25:54', 0),
(19, 20, 21, 'Ponto', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Ponto\r\n{\r\n   private int x;\r\n   private int y;\r\n   \r\n   public Ponto(){}\r\n   \r\n   public Ponto(int x, int y){\r\n       this.x = x;\r\n       this.y = y;\r\n   }\r\n   \r\n   public void setX(int x){\r\n       this.x = x;\r\n   }\r\n   \r\n   public int getX(){\r\n       return this.x;\r\n   }\r\n   \r\n   public void setY(int y){\r\n       this.y = y;\r\n   }\r\n  \r\n   public int getY(){\r\n       return this.y;\r\n   }\r\n   \r\n   public String toString(){\r\n       return "(" + this.x + ", " + this.y + ")";\r\n   }\r\n}', NULL, '2015-05-08 22:56:29', 0),
(20, 20, 21, 'Reta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Reta\r\n{\r\n   private Ponto p;\r\n   private Ponto q;\r\n   \r\n   public Reta(){}\r\n   \r\n   public Reta(Ponto p, Ponto q){\r\n       this.p = p;\r\n       this.q = q;\r\n   }\r\n   \r\n   public void setP(Ponto p){\r\n       this.p = p;\r\n   }\r\n   \r\n   public Ponto getP(){\r\n       return this.p;\r\n   }\r\n   \r\n   public void setQ(Ponto q){\r\n       this.q = q;\r\n   }\r\n   \r\n   public Ponto getQ(){\r\n       return q;\r\n   }\r\n   \r\n   public double getDistancia(){\r\n       return Math.sqrt((Math.pow((q.getX() - p.getX()),2) + Math.pow((q.getY() - p.getY()),2)));\r\n   }\r\n   \r\n}', NULL, '2015-05-08 23:05:59', 0),
(21, 20, 14, 'Ponto', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Ponto\r\n{\r\n   private int x,y;\r\n   \r\n   public Ponto(){}\r\n   \r\n   public Ponto(int x, int y){\r\n       this.x = x;\r\n       this.y = y;\r\n   }\r\n   \r\n   public void setX(int x){\r\n       this.x = x;\r\n   }\r\n   \r\n   public void setY(int y){\r\n       this.y = y;\r\n   }\r\n   \r\n   public int getX(){\r\n       return this.x;\r\n   }\r\n   \r\n   public int getY(){\r\n       return this.y;\r\n   }\r\n   \r\n   public String toString(){\r\n       return "(" + x + ", " + y + ")";\r\n   }\r\n}', NULL, '2015-05-10 01:42:49', 0),
(22, 20, 14, 'Reta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Reta {\r\n    Ponto p, q;\r\n    \r\n    public Reta(){}\r\n    \r\n    public Reta(Ponto p, Ponto q){\r\n        this.p = p;\r\n        this.q = q;\r\n    }\r\n    \r\n    public void setP(Ponto p){\r\n        this.p = p;\r\n    }\r\n    \r\n    public void setQ(Ponto q){\r\n        this.q = q;\r\n    }\r\n    \r\n    public Ponto getP(){\r\n        return this.p;\r\n    }\r\n    \r\n    public Ponto getQ(){\r\n        return this.q;\r\n    }\r\n   \r\n    public double getDistancia(){\r\n        double distancia =  Math.sqrt(Math.pow((this.q.getX() - this.p.getX()), 2) + Math.pow((this.q.getY() - this.p.getY()), 2));\r\n        return distancia;\r\n    }\r\n}', NULL, '2015-05-10 02:04:16', 0),
