(35, 21, 20, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n    private Ponto[] pontos;\r\n    private int tamanho;\r\n    \r\n    public ArrayDePontos (int capacidade) {\r\n        this.pontos = new Ponto [capacidade];\r\n    }\r\n    \r\n    public int getTamanho ( ) {\r\n        return tamanho;\r\n    }\r\n    \r\n    public void inserirPonto (Ponto p) {\r\n        try {\r\n            pontos[tamanho++] = p;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array já está cheio");\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoSuperior ( ) {\r\n        try {\r\n            Ponto pontoSuperior = pontos[0];\r\n        \r\n            for (int i = 1; i < tamanho; i++) \r\n                if (pontos[i].getY ( ) > pontoSuperior.getY ( )) \r\n                   pontoSuperior = pontos[i];\r\n     \r\n            return pontoSuperior;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array está vazio");\r\n            return null;\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoInferior ( ) {\r\n        try {\r\n            Ponto pontoInferior = pontos[0];\r\n        \r\n            for (int i = 1; i < tamanho; i++) \r\n                if (pontos[i].getY ( ) < pontoInferior.getY ( )) \r\n                   pontoInferior = pontos[i];\r\n                   \r\n            return pontoInferior;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array está vazio");\r\n            return null;\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisADireita ( ) {\r\n        try {\r\n            Ponto pontoMaisADireita = pontos[0];\r\n        \r\n            for (int i = 1; i < tamanho; i++) \r\n                if (pontos[i].getX ( ) > pontoMaisADireita.getX ( )) \r\n                   pontoMaisADireita = pontos[i];\r\n     \r\n            return pontoMaisADireita;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array está vazio");\r\n            return null;\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisAEsquerda ( ) {\r\n        try {\r\n            Ponto pontoMaisAEsquerda = pontos[0];\r\n        \r\n            for (int i = 1; i < tamanho; i++) \r\n                if (pontos[i].getX ( ) < pontoMaisAEsquerda.getX ( )) \r\n                   pontoMaisAEsquerda = pontos[i];\r\n     \r\n            return pontoMaisAEsquerda;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array está vazio");\r\n            return null;\r\n        }\r\n    }\r\n}\r\n', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n    private Ponto[] pontos;\r\n    private int tamanho;\r\n    \r\n    public ArrayDePontos (int capacidade) {\r\n        this.pontos = new Ponto [capacidade];\r\n    }\r\n    \r\n    public int getTamanho ( ) {\r\n        return tamanho;\r\n    }\r\n    \r\n    public void inserirPonto (Ponto p) {\r\n        try {\r\n            pontos[tamanho++] = p;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array já está cheio");\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoSuperior ( ) {\r\n        try {\r\n            Ponto pontoSuperior = pontos[0];\r\n        \r\n            for (int i = 1; i < tamanho; i++) \r\n                if (pontos[i].getY ( ) > pontoSuperior.getY ( ) \r\n                   pontoSuperior = pontos[i];\r\n     \r\n            return pontoSuperior;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array está vazio");\r\n            return null;\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoInferior ( ) {\r\