INSERT INTO `exercicioclasse` (`ID`, `IdExercicio`, `IdAluno`, `NomeClasse`, `Codigo`, `CodigoAnterior`, `DataCadastro`, `Favorito`) VALUES
(44, 21, 11, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n', NULL, '2015-05-20 09:57:26', 0),
(45, 21, 11, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n    int tamanho = 2;\r\n    Ponto[tamanho] ponto;\r\n    public ArrayDePontos () {\r\n        int pontos = 3;\r\n        ponto = new Ponto[pontos];\r\n    }\r\n    public int getTamanho () {\r\n        return tamanho;\r\n    }\r\n    public void inserirPonto () {\r\n    }\r\n}', NULL, '2015-05-21 00:17:23', 0),
(46, 22, 10, 'Socio', 'public class Socio {\r\n\r\n    private int numero;\r\n    private int idade;\r\n    private String nome;\r\n\r\n    public Socio() {\r\n        this.numero = 0;\r\n        this.idade = 0;\r\n        this.nome = "";\r\n    }\r\n\r\n    public Socio(int numero, int idade, String nome) {\r\n        this.numero = numero;\r\n        this.idade = idade;\r\n        this.nome = nome;\r\n    }\r\n\r\n    public int getNumero() {\r\n        return numero;\r\n    }\r\n\r\n    public void setNumero(int numero) {\r\n        this.numero = numero;\r\n    }\r\n\r\n    public int getIdade() {\r\n        return idade;\r\n    }\r\n\r\n    public void setIdade(int idade) {\r\n        this.idade = idade;\r\n    }\r\n\r\n    public String getNome() {\r\n        return nome;\r\n    }\r\n\r\n    public void setNome(String nome) {\r\n        this.nome = nome;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return numero + ", " + idade + ", " + nome;\r\n    }\r\n\r\n}\r\n', NULL, '2015-05-21 02:02:53', 0),
(47, 22, 10, 'SocioAtleta', 'public class SocioAtleta extends Socio {\r\n\r\n    private String categoria;\r\n\r\n    public SocioAtleta() {\r\n        super();\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome) {\r\n        super(numero, idade, nome);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    @Override\r\n    public void setIdade(int idade) {\r\n        super.setIdade(idade);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    private void atualizaCategoria() {\r\n\r\n        if (this.getIdade() <= 10) {\r\n            this.categoria = "Mirim";\r\n        } else if (this.getIdade() <= 15) {\r\n            this.categoria = "Infantil";\r\n        } else if (this.getIdade() <= 20) {\r\n            this.categoria = "Juvenil";\r\n        } else if (this.getIdade() <= 40) {\r\n            this.categoria = "Adulto";\r\n        } else {\r\n            this.categoria = "Master";\r\n        }\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return super.toString() + ", " + categoria;\r\n    }\r\n\r\n}\r\n', 'public class SocioAtleta extends Socio {\r\n\r\n    private String categoria;\r\n\r\n    public SocioAtleta() {\r\n        super();\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome) {\r\n        super(numero, idade, nome);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    @Override\r\n    public void setIdade(int idade) {\r\n        super.setIdade(idade);\r\n        \r\n    }\r\n\r\n    private void atualizaCategoria() {\r\n\r\n        if (this.getIdade() <= 10) {\r\n            this.categoria = "Mirim";\r\n        } else if (this.getIdade() <= 15) {\r\n            this.categoria = "Infantil";\r\n        } else if (this.getIdade() <= 20) {\r\n            this.categoria = "Juvenil";\r\n        } else if (this.getIdade() <= 40) {\r\n            this.categoria = "Adulto";\r\n        } else {\r\n            this.categoria = "Master";\r\n        }\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return super.toString() + ", " + categoria;\r\n    }\r\n\r\n}\r\n', '2015-05-21 03:16:24', 0),
(48, 21, 14, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n    Ponto[] pontos;\r\n    int tamanho;\r\n    \r\n    public ArrayDePontos(int nValores){\r\n        this.pontos = new Ponto[nValores];\r\n    }\r\n    \r\n    public int getTamanho(){\r\n        return this.tamanho;\r\n    }\r\n    \r\n    public void inserirPonto(Ponto ponto){\r\n        for(int i=0; i < this.pontos.length; i++){\r\n            if(this.pontos[i] == null){\r\n                this.pontos[i] = ponto;\r\n                tamanho++;\r\n            }\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoSuperior(){\r\n        Ponto pontoMaior = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getY() > pontoMaior.getY()){\r\n                pontoMaior = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMaior;\r\n    }\r\n    \r\n    public Ponto obtemPontoInferior(){\r\n        Ponto pontoMenor = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getY() < pontoMenor.getY()){\r\n                pontoMenor = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMenor;\r\n    }\r\n    \r\n     public Ponto obtemPontoMaisADireita(){\r\n        Ponto pontoMaior = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getX() > pontoMaior.getX()){\r\n                pontoMaior = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMaior;\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n        Ponto pontoMenor = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getX() < pontoMenor.getX()){\r\n                pontoMenor = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMenor;\r\n    }\r\n    \r\n}', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n    Ponto[] pontos;\r\n    int tamanho;\r\n    \r\n    public ArrayDePontos(int nValores){\r\n        this.pontos = new Ponto[nValores];\r\n    }\r\n    \r\n    public int getTamanho(){\r\n        return this.tamanho;\r\n    }\r\n    \r\n    public void inserirPonto(Ponto ponto){\r\n        for(int i=0; i<this.pontos.length; i++){\r\n            if(this.pontos[i] == null){\r\n                this.pontos[i] = ponto;\r\n                tamanho++;\r\n            } else {\r\n                \r\n            }\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoSuperior(){\r\n        Ponto pontoMaior = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getY() > pontoMaior.getY()){\r\n                pontoMaior = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMaior;\r\n    }\r\n    \r\n    public Ponto obtemPontoInferior(){\r\n        Ponto pontoMenor = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getY() < pontoMenor.getY()){\r\n                pontoMenor = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMenor;\r\n    }\r\n    \r\n     public Ponto obtemPontoMaisADireita(){\r\n        Ponto pontoMaior = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getX() > pontoMaior.getX()){\r\n                pontoMaior = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMaior;\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n        Ponto pontoMenor = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getX() < pontoMenor.getX()){\r\n                pontoMenor = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMenor;\r\n    }\r\n    \r\n}', '2015-05-21 22:35:14', 0);
INSERT INTO `exercicioclasseauxiliar` (`ID`, `IdExercicio`, `NomeClasse`, `Codigo`, `MostrarParaAluno`) VALUES
(1, 20, 'Ponto', '/**\r\n *\r\n * @author gilvani\r\n */\r\npublic class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + "," + y + '')'';\r\n    }\r\n}\r\n', 0),
(2, 20, 'Reta', '/*\r\n * To change this license header, choose License Headers in Project Properties.\r\n * To change this template file, choose Tools | Templates\r\n * and open the template in the editor.\r\n */\r\n\r\n/**\r\n *\r\n * @author gilvani\r\n */\r\npublic class Reta {\r\n\r\n    private Ponto p;\r\n    private Ponto q;\r\n\r\n    public Reta() {\r\n    }\r\n\r\n    public Reta(Ponto p, Ponto q) {\r\n        this.p = p;\r\n        this.q = q;\r\n    }\r\n\r\n    public Ponto getP() {\r\n        return p;\r\n    }\r\n\r\n    public void setP(Ponto p) {\r\n        this.p = p;\r\n    }\r\n\r\n    public Ponto getQ() {\r\n        return q;\r\n    }\r\n\r\n    public void setQ(Ponto q) {\r\n        this.q = q;\r\n    }\r\n\r\n    public double getDistancia() {\r\n        double x = Math.pow(q.getX() - p.getX(), 2);\r\n        double y = Math.pow(q.getY() - p.getY(), 2);\r\n        return Math.sqrt(x + y);\r\n    }\r\n}\r\n', 0),
(3, 21, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n', 1),
(4, 21, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n\r\n    private Ponto[] pontos;\r\n    private int tamanho;\r\n\r\n    public ArrayDePontos(int capacidade) {\r\n\r\n        this.tamanho = 0;\r\n        this.pontos = new Ponto[capacidade];\r\n    }\r\n\r\n    public int getTamanho() {\r\n        return this.tamanho;\r\n    }\r\n\r\n    public void inserirPonto(Ponto ponto) {\r\n        this.pontos[tamanho] = ponto;\r\n        this.tamanho++;\r\n    }\r\n\r\n    public Ponto obtemPontoSuperior() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto superior = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getY() > superior.getY()) {\r\n                superior = this.pontos[i];\r\n            }\r\n        }\r\n        return superior;\r\n    }\r\n\r\n    public Ponto obtemPontoInferior() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto inferior = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getY() < inferior.getY()) {\r\n                inferior = this.pontos[i];\r\n            }\r\n        }\r\n        return inferior;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisADireita() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto direita = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getX() > direita.getX()) {\r\n                direita = this.pontos[i];\r\n            }\r\n        }\r\n        return direita;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisAEsquerda() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto esquerda = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getX() < esquerda.getX()) {\r\n                esquerda = this.pontos[i];\r\n            }\r\n        }\r\n        return esquerda;\r\n    }\r\n}\r\n', 0),
(5, 22, 'Socio', 'public class Socio {\r\n\r\n    private int numero;\r\n    private int idade;\r\n    private String nome;\r\n\r\n    public Socio() {\r\n        this.numero = 0;\r\n        this.idade = 0;\r\n        this.nome = "";\r\n    }\r\n\r\n    public Socio(int numero, int idade, String nome) {\r\n        this.numero = numero;\r\n        this.idade = idade;\r\n        this.nome = nome;\r\n    }\r\n\r\n    public int getNumero() {\r\n        return numero;\r\n    }\r\n\r\n    public void setNumero(int numero) {\r\n        this.numero = numero;\r\n    }\r\n\r\n    public int getIdade() {\r\n        return idade;\r\n    }\r\n\r\n    public void setIdade(int idade) {\r\n        this.idade = idade;\r\n    }\r\n\r\n    public String getNome() {\r\n        return nome;\r\n    }\r\n\r\n    public void setNome(String nome) {\r\n        this.nome = nome;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return numero + ", " + idade + ", " + nome;\r\n    }\r\n\r\n}\r\n', 0),
(6, 22, 'SocioAtleta', 'public class SocioAtleta extends Socio {\r\n\r\n    private String categoria;\r\n\r\n    public SocioAtleta() {\r\n        super();\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome) {\r\n        super(numero, idade, nome);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    @Override\r\n    public void setIdade(int idade) {\r\n        super.setIdade(idade);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    private void atualizaCategoria() {\r\n\r\n        if (this.getIdade() <= 10) {\r\n            this.categoria = "Mirim";\r\n        } else if (this.getIdade() <= 15) {\r\n            this.categoria = "Infantil";\r\n        } else if (this.getIdade() <= 20) {\r\n            this.categoria = "Juvenil";\r\n        } else if (this.getIdade() <= 40) {\r\n            this.categoria = "Adulto";\r\n        } else {\r\n            this.categoria = "Master";\r\n        }\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return super.toString() + ", " + categoria;\r\n    }\r\n\r\n}\r\n', 0);
