(191, 99, 'Reta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Reta\r\n{\r\n    private Ponto p;\r\n    private Ponto q;\r\n    \r\n    public Reta(){\r\n    }\r\n    \r\n    public Reta(Ponto p, Ponto q){\r\n        this.p = p;\r\n        this.q = q;\r\n    }\r\n    \r\n    public void setP(Ponto p){\r\n        this.p = p;\r\n    }\r\n    \r\n    public void setQ(Ponto q){\r\n        this.q = q;\r\n    }\r\n    \r\n    public Ponto getP(){\r\n        return p;\r\n    }\r\n    \r\n    public Ponto getQ(){\r\n        return q;\r\n    }\r\n    \r\n    \r\n    public double getDistancia(){\r\n        double dist; \r\n        dist = (Math.sqrt(Math.pow(q.getX() - p.getX(), 2)) + (Math.pow(q.getY() - p.getY(), 2)));\r\n        return dist;\r\n        \r\n    }\r\n}                     ');
INSERT INTO `exerciciosolucaoclasse` (`ID`, `IdSolucao`, `NomeClasse`, `Codigo`) VALUES
(192, 100, 'Ponto', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Ponto\r\n{\r\n    private int x;\r\n    private int y;\r\n\r\n    public Ponto(){\r\n    }\r\n\r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n\r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX(){\r\n        return x;\r\n    }\r\n\r\n    public int getY(){\r\n        return y;\r\n    }\r\n\r\n    public String toString(){\r\n        String xy = "(" + getX() + ", " + getY() + ")";\r\n        return xy;\r\n    }\r\n\r\n}'),
(193, 100, 'Reta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Reta\r\n{\r\n    private Ponto p;\r\n    private Ponto q;\r\n    \r\n    public Reta(){\r\n    }\r\n    \r\n    public Reta(Ponto p, Ponto q){\r\n        this.p = p;\r\n        this.q = q;\r\n    }\r\n    \r\n    public void setP(Ponto p){\r\n        this.p = p;\r\n    }\r\n    \r\n    public void setQ(Ponto q){\r\n        this.q = q;\r\n    }\r\n    \r\n    public Ponto getP(){\r\n        return p;\r\n    }\r\n    \r\n    public Ponto getQ(){\r\n        return q;\r\n    }\r\n    \r\n    \r\n    public double getDistancia(){\r\n        double a = (Math.pow(q.getX() - p.getX(), 2));\r\n        double b = Math.pow(q.getY() - p.getY(), 2));\r\n        //double dist; \r\n        //dist = (Math.sqrt(Math.pow(q.getX() - p.getX(), 2)) + (Math.pow(q.getY() - p.getY(), 2)));\r\n        return Math.sqrt(a + b);\r\n        \r\n    }\r\n}                     '),
(194, 101, 'Ponto', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Ponto\r\n{\r\n    private int x;\r\n    private int y;\r\n\r\n    public Ponto(){\r\n    }\r\n\r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n\r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX(){\r\n        return x;\r\n    }\r\n\r\n    public int getY(){\r\n        return y;\r\n    }\r\n\r\n    public String toString(){\r\n        String xy = "(" + getX() + ", " + getY() + ")";\r\n        return xy;\r\n    }\r\n\r\n}'),
(195, 101, 'Reta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Reta\r\n{\r\n    private Ponto p;\r\n    private Ponto q;\r\n    \r\n    public Reta(){\r\n    }\r\n    \r\n    public Reta(Ponto p, Ponto q){\r\n        this.p = p;\r\n        this.q = q;\r\n    }\r\n    \r\n    public void setP(Ponto p){\r\n        this.p = p;\r\n    }\r\n    \r\n    public void setQ(Ponto q){\r\n        this.q = q;\r\n    }\r\n    \r\n    public Ponto getP(){\r\n        return p;\r\n    }\r\n    \r\n    public Ponto getQ(){\r\n        return q;\r\n    }\r\n    \r\n    \r\n    public double getDistancia(){\r\n        double a = Math.pow(q.getX() - p.getX(), 2);\r\n        double b = Math.pow(q.getY() - p.getY(), 2);\r\n        //double dist; \r\n        //dist = (Math.sqrt(Math.pow(q.getX() - p.getX(), 2)) + (Math.pow(q.getY() - p.getY(), 2)));\r\n        return Math.sqrt(a + b);\r\n        \r\n    }\r\n}                     '),
(196, 102, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + "," + y + '')'';\r\n    }\r\n}\r\n'),
(197, 102, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n    private Ponto[] pontos;\r\n    private int tamanho;\r\n    \r\n    public ArrayDePontos (int capacidade) {\r\n        this.pontos = new Ponto [capacidade];\r\n    }\r\n    \r\n    public int getTamanho ( ) {\r\n        return tamanho;\r\n    }\r\n    \r\n    public void inserirPonto (Ponto p) {\r\n        try {\r\n            pontos[tamanho++] = p;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array já está cheio");\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoSuperior ( ) {\r\n        try {\r\n            Ponto pontoSuperior = pontos[0];\r\n        \r\n            for (int i = 1; i < tamanho; i++) \r\n                if (pontos[i].getY ( ) > pontoSuperior.getY ( ) \r\n                   pontoSuperior = pontos[i];\r\n     \r\n            return pontoSuperior;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array está vazio");\r\n            return null;\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoInferior ( ) {\r\n        try {\r\n            Ponto pontoInferior = pontos[0];\r\n        \r\n            for (int i = 1; i < tamanho; i++) \r\n                if (pontos[i].getY ( ) < pontoInferior.getY ( ) \r\n                   pontoInferior = pontos[i];\r\n                   \r\n            return pontoInferior;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array está vazio");\r\n            return null;\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisADireita ( ) {\r\n        try {\r\n            Ponto pontoMaisADireita = pontos[0];\r\n        \r\n            for (int i = 1; i < tamanho; i++) \r\n                if (pontos[i].getX ( ) > pontoMaisADireita.getX ( ) \r\n                   pontoMaisADireita = pontos[i];\r\n     \r\n            return pontoMaisADireita;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array está vazio");\r\n            return null;\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisAEsquerda ( ) {\r\n        try {\r\n            Ponto pontoMaisAEsquerda = pontos[0];\r\n        \r\n            for (int i = 1; i < tamanho; i++) \r\n                if (pontos[i].getX ( ) < pontoMaisAEsquerda.getX ( ) \r\n                   pontoMaisAEsquerda = pontos[i];\r\n     \r\n            return pontoMaisAEsquerda;\r\n        } catch (ArrayIndexOutOfBoundsException e) {\r\n            System.out.println ("O array está vazio");\r\n            return null;\r\n        }\r\n    }\r\n}\r\n'),
