(213, 110, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos\r\n{\r\n    private Ponto[] pontos;\r\n    private int tamanho;\r\n    \r\n    public ArrayDePontos(int quantidadePontos){\r\n        this.pontos = new Ponto[quantidadePontos];\r\n        this.tamanho = 0;\r\n    }\r\n    \r\n    public int getTamanho(){\r\n        return this.tamanho;\r\n    }\r\n    \r\n    public void inserirPonto(Ponto ponto){\r\n        this.pontos[this.tamanho++] = ponto;\r\n    }\r\n    \r\n    public Ponto obtemPontoSuperior(){\r\n        Ponto superior = this.pontos[0];\r\n        for(int i = 1; i < this.tamanho; i++){\r\n            if(this.pontos[i].getY() > superior.getY()) superior = this.pontos[i];\r\n        }\r\n        return superior;\r\n    }\r\n    \r\n    public Ponto obtemPontoInferior(){\r\n        Ponto inferior = this.pontos[0];\r\n        for(int i = 1; i < this.tamanho; i++){\r\n            if(this.pontos[i].getY() < inferior.getY()) inferior = this.pontos[i];\r\n        }\r\n        return inferior;\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisADireita(){\r\n        Ponto maisADireita = this.pontos[0];\r\n        for(int i = 1; i < this.tamanho; i++){\r\n            if(this.pontos[i].getX() > maisADireita.getX()) maisADireita = this.pontos[i];\r\n        }\r\n        return maisADireita;\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n        Ponto maisAEsquerda = this.pontos[0];\r\n        for(int i = 1; i < this.tamanho; i++){\r\n            if(this.pontos[i].getX() < maisAEsquerda.getX()) maisAEsquerda = this.pontos[i];\r\n        }\r\n        return maisAEsquerda;\r\n    }\r\n}'),
(214, 111, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return this.x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + "," + y + '')'';\r\n    }\r\n}\r\n'),
(215, 111, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n\r\n    private Ponto[] pontos;\r\n    private int tamanho;\r\n\r\n    public ArrayDePontos(int capacidade) {\r\n\r\n        this.tamanho = 0;\r\n        this.pontos = new Ponto[capacidade];\r\n    }\r\n\r\n    public int getTamanho() {\r\n        return this.tamanho;\r\n    }\r\n\r\n    public void inserirPonto(Ponto ponto) {\r\n        this.pontos[tamanho] = ponto;\r\n        this.tamanho++;\r\n    }\r\n\r\n    public Ponto obtemPontoSuperior() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto superior = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getY() > superior.getY()) {\r\n                superior = this.pontos[i];\r\n            }\r\n        }\r\n        return superior;\r\n    }\r\n\r\n    public Ponto obtemPontoInferior() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto inferior = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getY() < inferior.getY()) {\r\n                inferior = this.pontos[i];\r\n            }\r\n        }\r\n        return inferior;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisADireita() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto direita = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getX() > direita.getX()) {\r\n                direita = this.pontos[i];\r\n            }\r\n        }\r\n        return direita;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisAEsquerda() {\r\n        if (this.tamanho == 0) {\r\n            return null;\r\n        }\r\n        Ponto esquerda = this.pontos[0];\r\n        for (int i = 1; i < tamanho; i++) {\r\n            if (this.pontos[i].getX() < esquerda.getX()) {\r\n                esquerda = this.pontos[i];\r\n            }\r\n        }\r\n        return esquerda;\r\n    }\r\n}\r\n'),
