(223, 115, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos\r\n{\r\n   private List<Ponto> arrayPontos; \r\n   \r\n   private Integer tamanho;\r\n   \r\n   public ArrayDePontos(Integer numMaxElem)\r\n   {\r\n       arrayPontos = Arrays.asList(numMaxElem);\r\n   }\r\n   \r\n   public Integer getTamanho(){\r\n       return this.tamanho;\r\n   }\r\n   \r\n   public void setTamanho(Integer num){\r\n       this.tamanho=num;\r\n   }\r\n   \r\n   public ArrayList<Pontos> getArrayPontos(){\r\n       return this.arrayPontos;\r\n   }\r\n   \r\n   public void setArrayPontos(ArrayList<Pontos> arrayPontos){\r\n       this.arrayPontos=arrayPontos;\r\n   }\r\n   \r\n   public void inserirPonto(Ponto ponto){\r\n       this.arrayPontos.add(ponto);\r\n       this.tamanho++;\r\n   }\r\n   \r\n   public Ponto obtemPontoSuperior(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (List<Ponto> ponto : this.arrayPontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getY() > p.getY())  \r\n               {\r\n                   p.setY(ponto.getY());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   public Ponto obtemPontoInferior(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (List<Ponto> ponto : this.arrayPontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getY() < p.getY())  \r\n               {\r\n                   p.setY(ponto.getY());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   public Ponto obtemPontoMaisADi